mapper.select:
SELECT
    id, biz_section, title, category_id, description, duration,
    total_score, pass_score, question_ids, status, created_at, updated_at
FROM t_paper
WHERE deleted = 0

    AND biz_section = #{q.bizSection}


    AND category_id = #{q.categoryId}


    AND status = #{q.status}


    AND title LIKE CONCAT('%', #{q.keyword}, '%')

ORDER BY id DESC
